import{_ as e,o,c as a,a5 as u}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"唤起第三方应用","description":"const navigateToLocation () \\\\ \\\\{ uni.openLocation(\\\\{ latitude: parseFloat(targetLatitude.value), // 纬度，浮点数，范围为90 90 longitude: parseFloat(ta。","frontmatter":{"title":"唤起第三方应用","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","浏览器与 Web API"],"description":"const navigateToLocation () \\\\ \\\\{ uni.openLocation(\\\\{ latitude: parseFloat(targetLatitude.value), // 纬度，浮点数，范围为90 90 longitude: parseFloat(ta。","sidebarWeight":78,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/blob/快速了解/唤起第三方应用.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/唤起第三方应用.md","filePath":"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/唤起第三方应用.md"}'),l={name:"posts/JavaScript系统教程/04-浏览器与 Web API/快速了解/唤起第三方应用.md"};function i(p,t,n,r,s,m){return o(),a("div",null,[...t[0]||(t[0]=[u('<div><h1 id="唤起第三方应用" tabindex="-1">唤起第三方应用 <a class="header-anchor" href="#唤起第三方应用" aria-label="Permalink to &quot;唤起第三方应用&quot;">​</a></h1><blockquote><p>本节目标：理解“唤起第三方应用”的核心思路，并能把它用于实际开发或面试表达。 const navigateToLocation = () =&gt; { uni.openLocation({ latitude: parseFloat(targetLatitude.value), // 纬度，浮点数，范围为90 ~ -90 longitude: parseFloat(targetLongitude.value), // 经度，浮点数，范围为180 ~ -180。 name: name.value, // 位置名 // address: &#39;&#39;, // 地址详情说明 scale: 16, // 地图缩放级别,整形值,范围从1~28。默认为16 success: function () { wxJsSdk.invoke(&#39;launch3rdApp&#39;, { &#39;appName&#39;: &#39;腾讯地图&#39;, &#39;appID&#39;: &#39;qqmap://map/&#39;, // iOS 使用 &#39;messageExt&#39;: &#39;from=qqmap://map/&#39;, // iOS 使用 &#39;packageName&#39;: &#39;com.tencent.map&#39;, // Android 使用 &#39;param&#39;: <code>type=&#39;driver&#39;&amp;from=${encodeURIComponent(address.value)},${latitude.value},${longitude.value}&amp;to=${encodeURIComponent(name.value)},${parseFloat(targetLatitude.value)},${parseFloat(targetLongitude.value)}</code> // Android 使用 }, function(res) { //alert(res.err_msg); // 调试日志输出 }); } }); };</p></blockquote><p>const urlTemplates = { android: { amap: <code>amapuri://route/plan/?sid=&amp;did=&amp;dlat=${latitude}&amp;dlon=${longitude}&amp;dname=${name}&amp;dev=0&amp;t=0</code>, qqmap: <code>qqmap://map/routeplan?type=drive&amp;to=${name}&amp;tocoord=${latitude},${longitude}&amp;referer=PFEBZ-PM2CL-JHKPH-MVN4Z-BC3G2-ZIF5I</code>, baidumap: <code>baidumap://map/direction?origin=${currentCoord.latitude},${currentCoord.longitude}&amp;destination=${destinationCoord.latitude},${destinationCoord.longitude}&amp;coord_type=gcj02&amp;mode=driving</code>, }, ios: { amap: <code>iosamap://path?sourceApplication=fuxishan_uni_client&amp;dlat=${latitude}&amp;dlon=${longitude}&amp;dname=${name}&amp;dev=0&amp;t=0</code>, qqmap: <code>qqmap://map/routeplan?type=drive&amp;fromcoord=${currentCoord.latitude},${currentCoord.longitude}&amp;tocoord=${latitude},${longitude}&amp;referer=PFEBZ-PM2CL-JHKPH-MVN4Z-BC3G2-ZIF5I</code>, baidumap: <code>baidumap://map/direction?origin=${currentCoord.latitude},${currentCoord.longitude}&amp;destination=${destinationCoord.latitude},${destinationCoord.longitude}&amp;coord_type=gcj02&amp;mode=driving</code>, }, };</p><p>uni-app 中如何打开外部应用，如：浏览器、淘宝、AppStore、QQ等 分类：uni-app ==打开外部应用== ==Runtime== ==plus== ==uniapp== ==scheme== ==schema== 我们在开发 App 应用中，经常会遇到打开第三方程序的场景，比如打开手机淘宝、通过第三方浏览器打开一个 url 等等。 App不像网页可以使用http超链接互相跳转，但手机os设计了scheme机制，可以通过特殊的链接互相调起。 比如手机淘宝，其安装后会在手机os中会注册一个scheme协议，taobao://。 这种协议还支持参数，比如taobao://s.taobao.com/search?q=uni-app启动淘宝并打开搜索页面搜索uni-app。 在uni-app/5+App中，可以通过scheme呼起其他App，也支持给自己的App设置scheme参数。 这个功能小程序并不支持，属于App端的扩展API。 打开外部scheme的API是plus.runtime.openURL()。查看文档： <a href="http://www.html5plus.org/doc/zh_cn/runtime.html" target="_blank" rel="noreferrer">http://www.html5plus.org/doc/zh_cn/runtime.html</a> 打开第三方程序 打开第三方程序，我们需要使用 <a href="http://www.html5plus.org/doc/zh_cn/runtime.html" target="_blank" rel="noreferrer">runtime</a> 模块,下面我罗列两个相关的方法。其他操作请详读文档。</p><ol start="10"><li>调用外部浏览器打开指定的URL==复制代码plus.runtime.openURL( url, errorCB, identity );==</li><li>url: ( String ) 必选 要打开的URL地址字符串类型，各平台支持的地址类型存在差异，参考平台URL支持表。</li><li>errorCB: ( OpenErrorCallback ) 可选 打开URL地址失败的回调打开指定URL地址失败时回调，并返回失败信息。</li><li>identity: ( String ) 可选 指定打开URL地址的程序名称在iOS平台此参数被忽略，在Android平台为程序包名，如果指定的包名不存在，则打开URL地址失败。==复制代码 &lt;====template====&gt;====&lt;====view====&gt;&lt;====button====class=========&quot;button&quot;====type=========&quot;primary&quot;====@====click=========&quot;open(0)&quot;====&gt;====使用第三方程序打开指定URL&lt;/====button====&gt;====&lt;/====view====&gt;&lt;/====template====&gt;========复制代码&lt;script&gt;== ======export====default===={== ==== ==data() {== ==== ==return===={== ==== ==url====:== ==&#39;====<a href="https://uniapp.dcloud.io/====&#39;====%5C" target="_blank" rel="noreferrer">https://uniapp.dcloud.io/====&#39;====\\</a>};== ==== ==},== ==== ==onLoad(op) {},== ==== ==methods====: {== ==== ==open(types) {== ==== ==plus.runtime.openURL(====this====.url,== ==function====(res) {== ==== ==console.log(res);== ==== ==});== ==== ==}== ==== ==}== ======};== ======&lt;/====script====&gt;==</li><li>调用第三方程序==复制代码plus.runtime.launchApplication( appInf, errorCB );==</li><li>appInf: ( ApplicationInf ) 必选 要启动第三方程序的描述信息</li><li>errorCB: ( LaunchErrorCallback ) 必选 启动第三方程序操作失败的回调函数启动第三方程序失败时回调，并返回失败信息。==复制代码 &lt;====template====&gt;====&lt;====view====&gt;&lt;====button====class=========&quot;button&quot;====type=========&quot;primary&quot;====@====click=========&quot;launchApp&quot;====&gt;====打开淘宝&lt;/====button====&gt;====&lt;/====view====&gt;&lt;/====template====&gt;========复制代码========&lt;script&gt;== ======export====default===={== ==== ==data() {== ==== ==return===={== ==== ==url====:== ==&#39;====<a href="https://uniapp.dcloud.io/====&#39;====%5C" target="_blank" rel="noreferrer">https://uniapp.dcloud.io/====&#39;====\\</a>};== ==== ==},== ==== ==onLoad(op) {},== ==== ==methods====: {== ==== ==launchApp() {== ==== ==let====_this === ==this====;== ==== ==// 判断平台== ==if====(plus.os.name ==== ==&#39;Android&#39;====) {== ==== ==plus.runtime.launchApplication(== ==== =={== ==== ==pname====:== ==&#39;com.taobao.taobao&#39;====},== ==== ==function====(e) {== ==== ==console.log(====&#39;Open system default browser failed: &#39;====+ e.message);== ==== ==}== ==== ==);== ==== ==}== ==else====if====(plus.os.name ==== ==&#39;iOS&#39;====) {== ==== ==plus.runtime.launchApplication({== ==action====:== ==&#39;taobao://&#39;====},== ==function====(e) {== ==== ==console.log(====&#39;Open system default browser failed: &#39;====+ e.message);== ==== ==});== ==== ==}== ==========}== ==== ==}== ======};== ======&lt;/====script====&gt;==</li></ol><p>常用URLscheme ==复制代码[== ==== ==// 只在 ios 中生效== ==== =={== ==== ==name: &#39;App Store&#39;,== ==== ==scheme: &#39;itms-apps://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;支付宝&#39;,== ==== ==pname: &#39;com.eg.android.AlipayGphone&#39;,== ==== ==scheme: &#39;alipay://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;淘宝&#39;,== ==== ==pname: &#39;com.taobao.taobao&#39;,== ==== ==scheme: &#39;taobao://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;QQ&#39;,== ==== ==pname: &#39;com.tencent.mobileqq&#39;,== ==== ==scheme: &#39;mqq://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;微信&#39;,== ==== ==pname: &#39;com.tencent.mm&#39;,== ==== ==scheme: &#39;weixin://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;京东&#39;,== ==== ==pname: &#39;com.jingdong.app.mall&#39;,== ==== ==scheme: &#39;openApp.jdMobile://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;新浪微博&#39;,== ==== ==pname: &#39;com.sina.weibo&#39;,== ==== ==scheme: &#39;sinaweibo://&#39;== ==== ==},== ==== =={== ==== ==name: &#39;优酷&#39;,== ==== ==pname: &#39;com.youku.phone&#39;,== ==== ==scheme: &#39;youku://&#39;== ==== ==}== ======]== ==== 更多实用例子 除了简单的打开App，我们更多的时候想要直达。这里汇总了很多有用的直达案例：</p><ol start="18"><li>使用应用商店打开指定App，可用于引导评分</li><li>强制使用应用宝打开指定App</li><li>打开淘宝搜索页面。需要你要做淘宝客，需要向淘宝申请自己的scheme参数并传入。</li><li>打开地图并指定地点</li><li>打开qq并到指定聊天界面，可用于客服具体代码见下：</li></ol><p>==复制代码&lt;====template====&gt;====&lt;====view====&gt;&lt;====page-head====title=========&quot;通过scheme打开三方app示例&quot;====&gt;&lt;/====page-head====&gt;&lt;====button====class=========&quot;button&quot;====@====click=========&quot;openBrowser(&#39;<a href="https://uniapp.dcloud.io/h5&#39;)%22====%5C%3E====%E4%BD%BF%E7%94%A8%E6%B5%8F%E8%A7%88%E5%99%A8%E6%89%93%E5%BC%80%E6%8C%87%E5%AE%9AURL%5C%3C/====button====%5C%3E====%5C%3C====button====class=========%22button%22====@====click=========%22openMarket()%22====%5C%3E====%E4%BD%BF%E7%94%A8%E5%BA%94%E7%94%A8%E5%95%86%E5%BA%97%E6%89%93%E5%BC%80%E6%8C%87%E5%AE%9AApp%5C%3C/====button====%5C%3E====%5C%3C====button====class=========%22button%22====@====click=========%22openMarket(&#39;com.tencent.android.qqdownloader&#39;)%22====%5C%3E====%E5%BC%BA%E5%88%B6%E4%BD%BF%E7%94%A8%E5%BA%94%E7%94%A8%E5%AE%9D%E6%89%93%E5%BC%80%E6%8C%87%E5%AE%9AApp%5C%3C/====button====%5C%3E====%5C%3C====button====class=========%22button%22====@====click=========%22openTaobao(&#39;taobao://s.taobao.com/search?q=uni-app" target="_blank" rel="noreferrer">https://uniapp.dcloud.io/h5&#39;)&quot;====\\&gt;====使用浏览器打开指定URL\\&lt;/====button====\\&gt;====\\&lt;====button====class=========&quot;button&quot;====@====click=========&quot;openMarket()&quot;====\\&gt;====使用应用商店打开指定App\\&lt;/====button====\\&gt;====\\&lt;====button====class=========&quot;button&quot;====@====click=========&quot;openMarket(&#39;com.tencent.android.qqdownloader&#39;)&quot;====\\&gt;====强制使用应用宝打开指定App\\&lt;/====button====\\&gt;====\\&lt;====button====class=========&quot;button&quot;====@====click=========&quot;openTaobao(&#39;taobao://s.taobao.com/search?q=uni-app</a>&#39;)&quot;====&gt;====打开淘宝搜索页面&lt;/====button====&gt;====&lt;====button====class=========&quot;button&quot;====@====click=========&quot;openMap()&quot;====&gt;====打开地图并指定地点&lt;/====button====&gt;====&lt;====view====class=========&quot;uni-divider&quot;====&gt;&lt;====view====class=========&quot;uni-divider__content&quot;====&gt;====打开QQ&lt;/====view====&gt;====&lt;====view====class=========&quot;uni-divider__line&quot;====&gt;&lt;/====view====&gt;&lt;/====view====&gt;&lt;====view====class=========&quot;uni-padding-wrap&quot;====&gt;&lt;====form====@====submit=========&quot;openQQ&quot;====&gt;&lt;====view====&gt;&lt;====view====class=========&quot;uni-title&quot;====&gt;====请输入聊天对象QQ号：&lt;/====view====&gt;====&lt;====view====class=========&quot;uni-list&quot;====&gt;&lt;====view====class=========&quot;uni-list-cell&quot;====&gt;&lt;====input====class=========&quot;uni-input&quot;====name=========&quot;qqNum&quot;====type=========&quot;number&quot;====/&gt;&lt;/====view====&gt;&lt;/====view====&gt;&lt;/====view====&gt;&lt;====view====&gt;&lt;====view====class=========&quot;uni-title&quot;====&gt;====请选择QQ号类型：&lt;/====view====&gt;====&lt;====radio-group====class=========&quot;uni-flex&quot;====name=========&quot;qqNumType&quot;====&gt;&lt;====label====&gt;&lt;====radio====value=========&quot;wpa&quot;====checked=========&quot;&quot;====/&gt;====普通QQ号&lt;/====label====&gt;====&lt;====label====&gt;&lt;====radio====value=========&quot;crm&quot;====/&gt;====营销QQ号(无需加好友直接聊天)&lt;/====label====&gt;====&lt;/====radio-group====&gt;&lt;/====view====&gt;&lt;====view====class=========&quot;uni-btn-v uni-common-mt&quot;====&gt;&lt;====button====class=========&quot;button&quot;====formType=========&quot;submit&quot;====&gt;====打开qq并到指定聊天界面&lt;/====button====&gt;====&lt;/====view====&gt;&lt;/====form====&gt;&lt;/====view====&gt;&lt;/====view====&gt;&lt;/====template====&gt;&lt;====script====&gt;== ======export====default===={== ==== ==data() {== ==== ==return===={== ==== ==};== ==== ==},== ==== ==methods====: {== ==== ==openBrowser(url){== ==== ==plus.runtime.openURL(url)== ==== ==},== ==== ==openMarket(marketPackageName) {== ==== ==var====appurl;== ==== ==if====(plus.os.name======&quot;Android&quot;====) {== ==== ==appurl === ==&quot;market://details?id=io.dcloud.HelloH5&quot;====;== ==//由于hello uni-app没有上Android应用商店，所以此处打开了另一个示例应用== ==}== ==== ==else===={== ==== ==appurl === ==&quot;itms-apps://itunes.apple.com/cn/app/hello-uni-app/id1417078253?mt=8&quot;====;== ==== ==}== ==== ==if====(====typeof====(marketPackageName)======&quot;undefined&quot;====) {== ==== ==plus.runtime.openURL(appurl,== ==function====(res)== =={== ==== ==console====.log(res);== ==== ==});== ==== ==}== ==else===={====//强制指定某个Android应用市场的包名，通过这个包名启动指定app== ==if====(plus.os.name======&quot;Android&quot;====) {== ==== ==plus.runtime.openURL(appurl,== ==function====(res)== =={== ==== ==plus.nativeUI.alert(====&quot;本机没有安装应用宝&quot;====);== ==== ==},marketPackageName);== ==== ==}== ==else===={== ==== ==plus.nativeUI.alert(====&quot;仅Android手机才支持应用宝&quot;====);== ==== ==}== ==== ==}== ==== ==},== ==== ==openTaobao(url){== ==== ==plus.runtime.openURL(url,== ==function====(res)== =={== ==== ==uni.showModal({== ==== ==content====:====&quot;本机未检测到淘宝客户端，是否打开浏览器访问淘宝？&quot;====,== ==== ==success====:====function====(res)===={== ==== ==if====(res.confirm) {== ==== ==plus.runtime.openURL(====&quot;<a href="https://s.taobao.com/search?q=uni-app" target="_blank" rel="noreferrer">https://s.taobao.com/search?q=uni-app</a>&quot;====)== ==== ==}== ==== ==}== ==== ==})== ==== ==});== ==== ==},== ==== ==openMap(){== ==== ==var====url === ==&quot;&quot;====;== ==== ==if====(plus.os.name======&quot;Android&quot;====) {== ==== ==var====hasBaiduMap = plus.runtime.isApplicationExist({====pname====:====&#39;com.baidu.BaiduMap&#39;====,====action====:====&#39;baidumap://&#39;====});== ==== ==var====hasAmap = plus.runtime.isApplicationExist({====pname====:====&#39;com.autonavi.minimap&#39;====,====action====:====&#39;androidamap://&#39;====});== ==== ==var====urlBaiduMap === ==&quot;baidumap://map/marker?location=39.968789,116.347247&amp;title=DCloud&amp;src=Hello%20uni-app&quot;====;== ==== ==var====urlAmap === ==&quot;androidamap://viewMap?sourceApplication=Hello%20uni-app&amp;poiname=DCloud&amp;lat=39.9631018208&amp;lon=116.3406135236&amp;dev=0&quot;====if====(hasAmap &amp;&amp; hasBaiduMap) {== ==== ==plus.nativeUI.actionSheet({====title====:====&quot;选择地图应用&quot;====,====cancel====:====&quot;取消&quot;====,====buttons====:[{====title====:====&quot;百度地图&quot;====},{====title====:====&quot;高德地图&quot;====}]},== ==function====(e)===={== ==== ==switch====(e.index){== ==== ==case====1:== ==== ==plus.runtime.openURL(urlBaiduMap);== ==== ==break====;== ==== ==case====2:== ==== ==plus.runtime.openURL(urlAmap);== ==== ==break====;== ==== ==}== ==== ==})== ==== ==}== ==== ==else====if====(hasAmap) {== ==== ==plus.runtime.openURL(urlAmap);== ==== ==}== ==== ==else====if====(hasBaiduMap) {== ==== ==plus.runtime.openURL(urlBaiduMap);== ==== ==}== ==== ==else===={== ==== ==url === ==&quot;geo:39.96310,116.340698?q=%e6%95%b0%e5%ad%97%e5%a4%a9%e5%a0%82&quot;====;== ==== ==plus.runtime.openURL(url);== ==//如果是国外应用，应该优先使用这个，会启动google地图。这个接口不能统一坐标系，进入百度地图时会有偏差== ==}== ==== ==}== ==else===={== ==== ==// iOS上获取本机是否安装了百度高德地图，需要在manifest里配置，在manifest.json文件app-plus-&gt;distribute-&gt;apple-&gt;urlschemewhitelist节点下添加（如urlschemewhitelist:[&quot;iosamap&quot;,&quot;baidumap&quot;]）== ==plus.nativeUI.actionSheet({====title====:====&quot;选择地图应用&quot;====,====cancel====:====&quot;取消&quot;====,====buttons====:[{====title====:====&quot;Apple地图&quot;====},{====title====:====&quot;百度地图&quot;====},{====title====:====&quot;高德地图&quot;====}]},== ==function====(e)===={== ==== ==console====.log(====&quot;e.index: &quot;====+ e.index);== ==== ==switch====(e.index){== ==== ==case====1:== ==== ==url === ==&quot;====<a href="http://maps.apple.com/?q=%e6%95%b0%e5%ad%97%e5%a4%a9%e5%a0%82&amp;ll=39.96310,116.340698&amp;spn=0.008766,0.019441====" target="_blank" rel="noreferrer">http://maps.apple.com/?q=数字天堂&amp;ll=39.96310,116.340698&amp;spn=0.008766,0.019441====</a>&quot;====;== ==== ==break====;== ==== ==case====2:== ==== ==url === ==&quot;baidumap://map/marker?location=39.968789,116.347247&amp;title=DCloud&amp;src=Hello%20uni-app&quot;====;== ==== ==break====;== ==== ==case====3:== ==== ==url === ==&quot;iosamap://viewMap?sourceApplication=Hello%20uni-app&amp;poiname=DCloud&amp;lat=39.9631018208&amp;lon=116.3406135236&amp;dev=0&quot;====;== ==== ==break====;== ==== ==default====:== ==== ==break====;== ==== ==}== ==== ==if====(url!=====&quot;&quot;====) {== ==== ==plus.runtime.openURL( url,== ==function====( e )== =={== ==== ==plus.nativeUI.alert(====&quot;本机未安装指定的地图应用&quot;====);== ==== ==});== ==== ==}== ==== ==})== ==== ==}== ==== ==},== ==== ==openQQ====:== ==function====(e)== =={== ==== ==// console.log(&quot;e.detail.value: &quot; + JSON.stringify(e.detail.value));== ==// 没有校验qq号是否为空或合法数字，如果不是可用的qq号，启动qq后会停留在qq主界面== ==plus.runtime.openURL(====&#39;mqqwpa://im/chat?chat_type=&#39;====+ e.detail.value.qqNumType +== ==&#39;&amp;uin=&#39;====+ e.detail.value.qqNum,====function====(res)== =={== ==== ==plus.nativeUI.alert(====&quot;本机没有安装QQ，无法启动&quot;====);== ==== ==});== ==== ==}== ==== ==}== ======};== ======&lt;/====script====&gt;&lt;====style====&gt;== ======.button===={== ==== ==margin====:== ==30====upx;== ==== ==color====:== ==#007AFF====;== ======}== ======&lt;/====style====&gt;== 给自己的App设置scheme 可在manifest中可配置。 <a href="https://ask.dcloud.net.cn/article/409" target="_blank" rel="noreferrer">Android</a>配置方法 <a href="http://ask.dcloud.net.cn/article/64" target="_blank" rel="noreferrer">iOS</a>配置方法</p></div>',1)])])}const q=e(l,[["render",i]]);export{d as __pageData,q as default};
